#include <string>
#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    int beautySum(string s) {
        int res = 0;
        for (int i = 0; i < s.size(); ++i) {
            vector<int> count(26, 0);
            for (int j = i; j < s.size(); ++j) {
                count[s[j] - 'a']++;
                int mx = 0, mn = INT_MAX;
                for (int c : count) {
                    if (c == 0) continue;
                    mx = max(mx, c);
                    mn = min(mn, c);
                }
                res += mx - mn;
            }
        }
        return res;
    }
};
